//! Games added by hand to the Heroic Games Launcher (Linux): "Add a game" entries in Heroic's
//! `sideload_apps/library.json`, launched through `heroic://launch/sideload/<appName>`.
//!
//! These are their own provider (`heroic`) because the apps belong to no store: their ids are
//! random strings generated by Heroic and mean nothing outside it.

use std::path::PathBuf;

use super::heroic::{self, HeroicPaths};
use super::{ImageCandidate, LibraryProvider, ProviderError};
use crate::model::ImportedGame;

pub const HEROIC_SOURCE: &str = "heroic";

#[derive(Debug, Clone, Default)]
pub struct HeroicSideloadProvider {
    paths: HeroicPaths,
    /// Only Linux has Heroic; elsewhere the provider reports itself as not scannable.
    enabled: bool,
}

impl HeroicSideloadProvider {
    /// Looks at the real environment (see [`HeroicPaths::detect`]).
    pub fn detect() -> Self {
        Self {
            paths: HeroicPaths::detect(),
            enabled: cfg!(not(windows)),
        }
    }

    pub fn with_paths(paths: HeroicPaths) -> Self {
        Self {
            paths,
            enabled: true,
        }
    }
}

/// Heroic's `art_cover` is a URL or a local path, with or without `file://`.
fn cover_candidate(cover: &str) -> Option<ImageCandidate> {
    if cover.starts_with("https://") || cover.starts_with("http://") {
        return Some(ImageCandidate::Url(cover.to_string()));
    }
    let path = PathBuf::from(cover.strip_prefix("file://").unwrap_or(cover));
    (path.is_absolute() && path.is_file()).then_some(ImageCandidate::File(path))
}

impl LibraryProvider for HeroicSideloadProvider {
    fn id(&self) -> &str {
        HEROIC_SOURCE
    }

    fn name(&self) -> &str {
        "Heroic (sideloaded)"
    }

    fn can_scan(&self) -> bool {
        self.enabled
    }

    fn scan_installed(&self) -> Result<Vec<ImportedGame>, ProviderError> {
        if !self.enabled {
            return Err(ProviderError::NotFound(
                "Heroic is only available on Linux".into(),
            ));
        }
        heroic::sideload_games(&self.paths)
    }

    fn cover_candidates(&self, source_game_id: &str) -> Vec<ImageCandidate> {
        heroic::sideload_apps(&self.paths)
            .into_iter()
            .find(|a| a.app_name == source_game_id)
            .and_then(|a| a.cover)
            .and_then(|c| cover_candidate(&c))
            .into_iter()
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use std::fs;

    use super::*;

    #[test]
    fn scans_and_finds_covers() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        let dir = home.join("Games/Indie");
        fs::create_dir_all(&dir).unwrap();
        let exe = dir.join("indie.exe");
        fs::write(&exe, "").unwrap();
        let cover = home.join("indie.png");
        fs::write(&cover, "x").unwrap();
        let lib = home.join(".config/heroic/sideload_apps/library.json");
        fs::create_dir_all(lib.parent().unwrap()).unwrap();
        fs::write(
            &lib,
            serde_json::json!({"games": [
                {"app_name": "a", "title": "Indie", "install": {"executable": exe, "platform": "Windows"},
                 "art_cover": cover},
                {"app_name": "b", "title": "Remote", "install": {"executable": exe, "platform": "linux"},
                 "art_cover": "https://i/b.jpg"},
                {"app_name": "c", "title": "Missing", "install": {"executable": exe},
                 "art_cover": "/nope.png"}
            ]})
            .to_string(),
        )
        .unwrap();
        let p = HeroicSideloadProvider::with_paths(HeroicPaths::discover(home, None, None));
        assert_eq!((p.id(), p.name()), ("heroic", "Heroic (sideloaded)"));
        assert!(!p.can_scan_owned());
        assert_eq!(p.scan_installed().unwrap().len(), 3);
        assert_eq!(
            p.cover_candidates("a"),
            vec![ImageCandidate::File(cover.clone())]
        );
        assert_eq!(
            p.cover_candidates("b"),
            vec![ImageCandidate::Url("https://i/b.jpg".into())]
        );
        assert!(p.cover_candidates("c").is_empty());
        assert!(p.cover_candidates("zzz").is_empty());
    }

    #[test]
    fn disabled_without_heroic() {
        let p = HeroicSideloadProvider::default();
        assert!(!p.can_scan());
        assert!(matches!(
            p.scan_installed(),
            Err(ProviderError::NotFound(_))
        ));
    }
}
